#!/usr/bin/env python3
"""Regenerate ventures/iban-list-check/iban-registry.mjs from python-stdnum's copy
of the SWIFT IBAN Registry (stdnum/iban.dat). Run after a stdnum upgrade:

    python3 platform/ci/id_oracle/registry_table.py > ventures/iban-list-check/iban-registry.mjs
"""
import os
import re

from stdnum import iban
from importlib.metadata import version

HEADER = """// BBAN structure per IBAN country, from the SWIFT IBAN Registry, release {rel}, as python-stdnum {ver} carries it
// (stdnum/iban.dat, "generated from iban-registry-v{rel}.txt"). Generated by platform/ci/id_oracle/registry_table.py;
// do not edit by hand. Each entry is runs of n (digits), a (capital letters) and c (letters or digits), e.g. "n8n10"
// collapsed to "n18". The registry is SWIFT's public document; these are facts about the format, not copied code.
export const BBAN_STRUCTURE = {{"""

FOOTER = r"""};

const CLASS = { n: "\\d", a: "[A-Z]", c: "[A-Z0-9]" };
const cache = new Map();
// The regular expression a country's BBAN (the IBAN after its first four characters) must match, or null.
export function bbanRegex(cc) {
  if (!cache.has(cc)) {
    const s = BBAN_STRUCTURE[cc];
    cache.set(cc, s ? new RegExp("^" + s.replace(/([nac])(\d+)/g, (_, k, n) => `${CLASS[k]}{${n}}`) + "$") : null);
  }
  return cache.get(cc);
}
// Total IBAN length per country: 4 plus the BBAN length.
export const ibanLength = (cc) => {
  const s = BBAN_STRUCTURE[cc];
  return s ? 4 + [...s.matchAll(/\d+/g)].reduce((a, m) => a + Number(m[0]), 0) : undefined;
};"""


def main():
    path = os.path.join(os.path.dirname(iban.__file__), "iban.dat")
    text = open(path, encoding="utf-8").read()
    rel = re.search(r"iban-registry-v(\d+)", text).group(1)
    table = {}
    for line in text.splitlines():
        m = re.match(r'^([A-Z]{2}) .*bban="([^"]+)"', line)
        if not m:
            continue
        runs = []
        for n, k in re.findall(r"(\d+)!([nac])", m.group(2)):
            if runs and runs[-1][1] == k:
                runs[-1][0] += int(n)
            else:
                runs.append([int(n), k])
        table[m.group(1)] = "".join(f"{k}{n}" for n, k in runs)
    print(HEADER.format(rel=rel, ver=version("python-stdnum")))
    items = sorted(table.items())
    for i in range(0, len(items), 6):
        print("  " + " ".join(f'{k}: "{v}",' for k, v in items[i:i + 6]))
    print(FOOTER)


if __name__ == "__main__":
    main()
